UT: [Contract C012] Precondition — Command serialization established
  ```rust
  // Verify RuntimeCommand is dispatched via UnboundedSender and processed in FIFO order
  let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
  let (reply1, ack1) = tokio::sync::oneshot::channel();
  let (reply2, ack2) = tokio::sync::oneshot::channel();

  tx.send(DispatchCommand::Execute { f: Box::new(|_| Ok(())) , reply: reply1 }).unwrap();
  tx.send(DispatchCommand::Execute { f: Box::new(|_| Ok(())) , reply: reply2 }).unwrap();

  // Verify FIFO: first sent = first received
  match rx.try_recv() { Ok(DispatchCommand::Execute { .. }) => {}, _ => panic!("expected Execute") }
  match rx.try_recv() { Ok(DispatchCommand::Execute { .. }) => {}, _ => panic!("expected Execute") }
  ```
