  let (client, _rx) = SipClient::new(config).await.unwrap();
  client.add_account(valid_account_config()).await.unwrap();
  // Internally, this submits RuntimeCommand::AddAccount via RuntimeHandle
  // Verified by MockBackend recording the call
  ```
  Invariant — API is Send+Sync
