C045-Post: ShutdownCommandRouter routes correctly
  ```rust
  use crate::error::m20_shutdown_routing::{ShutdownCommandRouter, ShutdownCommandAction};
  // GetAccountInfo permitted
  let cmd = make_get_account_info();
  let action = ShutdownCommandRouter::classify(&cmd, true);
  assert!(matches!(action, ShutdownCommandAction::Permit));
  // ConfConnect rejected
  let cmd = make_conf_connect();
  let action = ShutdownCommandRouter::classify(&cmd, true);
  assert!(matches!(action, ShutdownCommandAction::Reject(_)));
  // Non-M20 rejected
  let cmd = make_other_command();
  let action = ShutdownCommandRouter::classify(&cmd, true);
  assert!(matches!(action, ShutdownCommandAction::Reject(_)));
  // All permitted when not shutting down
  let action = ShutdownCommandRouter::classify(&cmd, false);
  assert!(matches!(action, ShutdownCommandAction::Permit));
  ```

