fn all_public_client_methods_are_instrumented() -> Result<(), std::io::Error> {
    // Postcondition (C047): tracing spans specified for all public operations.
    // Re-inspection O-001: the checks are a COMPLETE enumeration of the public
    // surface — SipClient 14 methods, SipAccountHandle 9 methods. Removing any
    // #[instrument] (including on the newly instrumented new/id) fails red.
    let checks: [(&str, &[&str]); 2] = [
        (
            "src/client.rs", // SipClient — 14 public methods
            &[
                "new", "handle", "subscribe", "subscribe_account",
                "subscribe_raw_sip", "accounts", "add_account", "remove_account",
                "account", "add_transport", "call_state", "subscribe_audio",
                "is_terminated", "shutdown",
            ],
        ),
        (
            "src/api/public_api_design.rs", // SipAccountHandle — 9 public methods
            &[
                "new", "id", "register", "unregister",
                "set_registration_enabled", "registration_state", "make_call",
                "update_config", "remove",
            ],
        ),
    ];
    for (path, methods) in checks {
        let src = std::fs::read_to_string(path)?;
        for method in methods {
            let (idx, _) = src
                .lines()
                .enumerate()
                .find(|(_, l)| {
                    let trimmed_line = l.trim_start();
                    trimmed_line.starts_with("pub ")
                        && trimmed_line.contains(&format!("fn {method}("))
                })
                .unwrap_or_else(|| panic!("{path} must define a public fn {method}("));
            let context: Vec<&str> = src.lines().skip(idx.saturating_sub(6)).take(6).collect();
            assert!(
