// C036-Post — pushed pair produces a paired stereo frame (L=IN, R=OUT)
#[test]
fn pipeline_produces_paired_stereo_frame() {
    let mut pipeline = valid_pipeline();
    let in_data: Vec<i16> = (1..=160).collect();
    let out_data: Vec<i16> = (101..=260).collect();
    let pair = AudioChunkPair {
        call_id: CallId::from_u64(1).unwrap(),
        account_id: AccountId::from_u64(1).unwrap(),
        timestamp: SystemTime::now(),
        in_chunk: AudioChunk::I16(in_data.clone()),
        out_chunk: AudioChunk::I16(out_data.clone()),
    };
    pipeline.push_pair(pair).unwrap();
    let frame = pipeline.poll_processed_frame().unwrap().unwrap();
    assert_eq!(frame.stereo_interleaved.len(), 320);
    for i in 0..160 {
        assert_eq!(frame.stereo_interleaved[2 * i], in_data[i], "L=IN at {i}");
        assert_eq!(frame.stereo_interleaved[2 * i + 1], out_data[i], "R=OUT at {i}");
    }
    assert_eq!(frame.negotiated_codec, NegotiatedCodec::Opus(OpusConfig::default()));
}

// C036-Inv — only IN fed past tolerance -> OUT zero-filled, drift incremented
#[test]
fn pipeline_zero_pads_missing_out_side() {
    let mut pipeline = valid_pipeline(); // tolerance = 20ms
    let in_data: Vec<i16> = (1..=160).collect();
    pipeline.push_in_frame(in_data.clone()).unwrap();
    std::thread::sleep(Duration::from_millis(50)); // 50ms > 20ms tolerance
    let frame = pipeline.poll_processed_frame().unwrap().unwrap();
    assert_eq!(frame.stereo_interleaved.len(), 320);
    for i in 0..160 {
        assert_eq!(frame.stereo_interleaved[2 * i], in_data[i], "L=IN preserved at {i}");
        assert_eq!(frame.stereo_interleaved[2 * i + 1], 0, "R=zero-padded at {i}");
    }
    assert!(pipeline.alignment_drift() > 0);
}

