UT: [Normal] C033-Post: SyncAudioSource::next_chunk fills the buffer and returns the sample count
  ```rust
  struct TestSource(Vec<i16>, usize);
  impl SyncAudioSource for TestSource {
      fn next_chunk(&mut self, buf: &mut [i16]) -> usize {
          let remaining = self.0.len() - self.1;
          let to_copy = remaining.min(buf.len());
          if to_copy > 0 {
              buf[..to_copy].copy_from_slice(&self.0[self.1..self.1 + to_copy]);
              self.1 += to_copy;
          }
          to_copy
      }
  }
  let mut src = TestSource(vec![10i16, 20i16, 30i16], 0);
  let mut buf = [0i16; 4];
  let n = SyncAudioSource::next_chunk(&mut src, &mut buf);
  assert_eq!(n, 3);
  assert_eq!(buf[0], 10);
  assert_eq!(buf[2], 30);
  ```

