  // [::TICKET::] P13-2: O-001 closure — the default build graph must be cpal-free.
  use std::path::Path;
  use std::process::Command;

  #[test]
  fn cargo_toml_keeps_cpal_optional_behind_cpal_input() -> Result<(), String> {
      let manifest = Path::new(env!("CARGO_MANIFEST_DIR")).join("Cargo.toml");
      let text =
          std::fs::read_to_string(&manifest).map_err(|e| format!("read Cargo.toml: {e}"))?;
      assert!(
          text.contains("cpal = { version = \"0.18\", optional = true }"),
          "cpal must stay optional in Cargo.toml"
      );
      assert!(
          text.contains("cpal-input = [\"dep:cpal\"]"),
          "cpal-input must pull dep:cpal"
      );
      Ok(())
  }

  #[test]
  fn default_build_graph_is_cpal_free_and_feature_adds_it() -> Result<(), String> {
      let manifest = Path::new(env!("CARGO_MANIFEST_DIR")).join("Cargo.toml");
      let default_tree = run_cargo_tree(&manifest, &[])?;
      assert!(
          !contains_cpal(&default_tree),
          "default build graph must be cpal-free:\n{default_tree}"
      );
      let feature_tree = run_cargo_tree(&manifest, &["--features", "cpal-input"])?;
      assert!(
          contains_cpal(&feature_tree),
          "cpal-input must add cpal to the graph:\n{feature_tree}"
      );
      Ok(())
  }

  fn run_cargo_tree(manifest: &Path, extra: &[&str]) -> Result<String, String> {
      let output = Command::new("cargo")
          .arg("tree")
          .arg("-e")
          .arg("normal")
          .args(["--offline", "--locked"])
          .arg("--manifest-path")
          .arg(manifest)
          .args(extra)
          .output()
          .map_err(|e| format!("spawn cargo tree: {e}"))?;
      if !output.status.success() {
          return Err(format!(
              "cargo tree failed: {}: {}",
              output.status,
              String::from_utf8_lossy(&output.stderr)
          ));
      }
      String::from_utf8(output.stdout).map_err(|e| format!("cargo tree output not UTF-8: {e}"))
  }

  fn contains_cpal(tree_output: &str) -> bool {
      tree_output.lines().any(|line| line.split_whitespace().next() == Some("cpal"))
  }
